import "./field.css";

import {

  Children,
  cloneElement,
  isValidElement,
  useId,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
} from "react";
import { cx } from "./cx";

export function describedBy(
  ...parts: Array<string | false | null | undefined>
): string | undefined {
  const value = parts.filter((part): part is string => Boolean(part)).join(" ");
  return value || undefined;
}

export const TEXT_FIELD_TYPES = [
  "text",
  "email",
  "password",
  "url",
  "tel",
  "search",
  "number",
] as const;

export type TextFieldType = (typeof TEXT_FIELD_TYPES)[number];

export type FieldChrome = {
  label: ReactNode;
  optional?: boolean | undefined;
  required?: boolean | undefined;
  optionalLabel?: ReactNode | undefined;
  requiredLabel?: ReactNode | undefined;
  description?: ReactNode | undefined;
  error?: ReactNode | undefined;
  className?: string | undefined;
  chrome?: "stack" | "float" | "placeholder" | undefined;
};

export type FieldKind = "well" | "choice" | "select";

type ControlProps = {
  id?: string | undefined;
  disabled?: boolean | undefined;
  readOnly?: boolean | undefined;
  required?: boolean | undefined;
  "aria-invalid"?: boolean | "true" | "false" | undefined;
  "aria-describedby"?: string | undefined;
  "aria-required"?: boolean | undefined;
};

export type FieldProps = FieldChrome & {
  id?: string | undefined;
  disabled?: boolean | undefined;
  readOnly?: boolean | undefined;
  multiline?: boolean | undefined;
  kind?: FieldKind | undefined;
  invalid?: boolean | undefined;
  children: ReactElement<ControlProps>;
};

export type TextFieldProps = Omit<
  ComponentProps<"input">,
  "size" | "className" | "type"
> &
  FieldChrome & {
    type?: TextFieldType | undefined;
  };

export type TextAreaProps = Omit<ComponentProps<"textarea">, "className"> &
  FieldChrome;

type TypeDefaults = Pick<
  ComponentProps<"input">,
  "autoCapitalize" | "autoComplete" | "enterKeyHint" | "spellCheck"
>;

function isTextFieldType(type: string): type is TextFieldType {
  return (TEXT_FIELD_TYPES as readonly string[]).includes(type);
}

function resolveType(type: string | undefined): TextFieldType {
  const next = type ?? "text";
  if (isTextFieldType(next)) return next;
  if (process.env.NODE_ENV !== "production") {
    console.warn(
      `TextField: type="${type}" is not supported. Use text, email, password, url, tel, search, or number.`,
    );
  }
  return "text";
}

export function FieldMark({
  optional,
  required,
  optionalLabel = "Optional",
  requiredLabel = "Required",
}: {
  optional?: boolean | undefined;
  required?: boolean | undefined;
  optionalLabel?: ReactNode | undefined;
  requiredLabel?: ReactNode | undefined;
}) {
  if (optional) {
    return <span className="ns-field__optional"> {optionalLabel}</span>;
  }
  if (required) {
    return <span className="ns-field__required"> {requiredLabel}</span>;
  }
  return null;
}

function defaultsForType(type: string | undefined): TypeDefaults {
  switch (type) {
    case "email":
      return {
        spellCheck: false,
        autoCapitalize: "off",
        autoComplete: "email",
      };
    case "password":
      return {
        spellCheck: false,
        autoCapitalize: "off",
        autoComplete: "current-password",
      };
    case "url":
      return {
        spellCheck: false,
        autoCapitalize: "off",
        autoComplete: "url",
      };
    case "tel":
      return { spellCheck: false, autoComplete: "tel" };
    case "search":
      return { enterKeyHint: "search", autoComplete: "off" };
    default:
      return {};
  }
}

function textPlaceholder(
  chrome: FieldChrome["chrome"],
  label: ReactNode,
  placeholder: string | undefined,
) {
  if (chrome === "placeholder" && typeof label === "string") return label;
  return placeholder;
}

export function Field({
  label,
  optional,
  required,
  optionalLabel,
  requiredLabel,
  description,
  error,
  className,
  chrome = "stack",
  id,
  disabled,
  readOnly,
  multiline,
  kind = "well",
  invalid: invalidProp,
  children,
}: FieldProps) {
  const generatedId = useId();
  const child = Children.only(children);
  const childProps = isValidElement<ControlProps>(child) ? child.props : {};
  const inputId = id ?? childProps.id ?? generatedId;
  const descriptionId = `${inputId}-desc`;
  const errorId = `${inputId}-error`;
  const invalid =
    invalidProp === true ||
    error != null ||
    childProps["aria-invalid"] === true ||
    childProps["aria-invalid"] === "true";
  const requireControl = Boolean(required) && !optional;
  const placeholder = kind === "well" && chrome === "placeholder";
  const float = kind !== "choice" && chrome === "float";
  const stack = kind !== "choice" && chrome === "stack";
  const labelMode = kind === "choice" ? undefined : chrome;
  const mark = (
    <FieldMark
      optional={optional}
      required={required}
      optionalLabel={optionalLabel}
      requiredLabel={requiredLabel}
    />
  );

  const control = isValidElement<ControlProps>(child)
    ? cloneElement(child, {
        id: inputId,
        disabled: disabled ?? childProps.disabled,
        ...(readOnly != null ? { readOnly } : {}),
        required: requireControl || childProps.required,
        "aria-required": requireControl || childProps.required || undefined,
        "aria-invalid": invalid || undefined,
        "aria-describedby": describedBy(
          description != null && descriptionId,
          error != null && errorId,
          childProps["aria-describedby"],
        ),
      })
    : child;

  const visibleLabel = (
    <label className="ns-field__label" htmlFor={inputId}>
      {label}
      {mark}
    </label>
  );

  return (
    <div
      className={cx("ns-field", className)}
      data-invalid={invalid ? "true" : undefined}
      data-disabled={disabled ? "true" : undefined}
      data-readonly={readOnly ? "true" : undefined}
      data-multiline={multiline ? "true" : undefined}
      data-kind={kind === "well" ? undefined : kind}
      data-label={labelMode}
    >
      {placeholder ? (
        <label className="ns-sr ns-field__sr" htmlFor={inputId}>
          {label}
          {mark}
        </label>
      ) : null}
      {stack || float ? visibleLabel : null}
      <div className="ns-field__control">
        {control}
        {kind === "choice" ? visibleLabel : null}
      </div>
      {description != null || error != null ? (
        <div className="ns-field__meta">
          {description != null ? (
            <div className="ns-field__description" id={descriptionId}>
              {description}
            </div>
          ) : null}
          {error != null ? (
            <div className="ns-field__error" id={errorId}>
              {error}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export function TextField({
  label,
  optional,
  required,
  optionalLabel,
  requiredLabel,
  description,
  error,
  className,
  chrome,
  id,
  type = "text",
  disabled,
  readOnly,
  placeholder,
  ...rest
}: TextFieldProps) {
  const resolvedType = resolveType(type);

  return (
    <Field
      id={id}
      label={label}
      optional={optional}
      required={required}
      optionalLabel={optionalLabel}
      requiredLabel={requiredLabel}
      description={description}
      error={error}
      className={className}
      chrome={chrome}
      disabled={disabled}
      readOnly={readOnly}
    >
      <input
        {...defaultsForType(resolvedType)}
        {...rest}
        className="ns-field__input"
        type={resolvedType}
        placeholder={textPlaceholder(chrome, label, placeholder)}
      />
    </Field>
  );
}

export function TextArea({
  label,
  optional,
  required,
  optionalLabel,
  requiredLabel,
  description,
  error,
  className,
  chrome,
  id,
  disabled,
  readOnly,
  rows = 4,
  placeholder,
  ...rest
}: TextAreaProps) {
  return (
    <Field
      id={id}
      label={label}
      optional={optional}
      required={required}
      optionalLabel={optionalLabel}
      requiredLabel={requiredLabel}
      description={description}
      error={error}
      className={className}
      chrome={chrome}
      disabled={disabled}
      readOnly={readOnly}
      multiline
    >
      <textarea
        {...rest}
        className="ns-field__input"
        rows={rows}
        placeholder={textPlaceholder(chrome, label, placeholder)}
      />
    </Field>
  );
}

@layer components {
  .ns-field {
    --ns-field-fg: var(--text-heading, #111);
    --ns-field-body: var(--text-body, #444);
    --ns-field-muted: var(--text-sub, #767676);
    --ns-field-fill: var(--bg, #fff);
    --ns-field-line: var(
      --line,
      color-mix(in srgb, var(--ns-field-fg) 12%, transparent)
    );
    --ns-field-line-strong: var(
      --focus,
      color-mix(in srgb, var(--text-heading, #111) 70%, transparent)
    );
    --ns-field-error: var(--error, #8f3232);
    --ns-field-radius: var(--radius, 0.4rem);
    --ns-field-inset-y: var(--space-5, 0.61rem);
    --ns-field-inset-x: var(--space-6, 0.76rem);

    display: flex;
    flex-direction: column;
    gap: var(--space-2, 0.31rem);
    min-width: 0;
    color: var(--ns-field-body);
  }

  [data-density="compact"] .ns-field {
    --ns-field-inset-y: var(--space-3, 0.39rem);
    --ns-field-inset-x: var(--space-4, 0.49rem);
  }

  .ns-field__control {
    position: relative;
    box-sizing: border-box;
    min-width: 0;
    height: calc(1em * var(--leading, 1.5625) + var(--ns-field-inset-y) * 2);
    border: 1px solid var(--ns-field-line);
    border-radius: var(--ns-field-radius);
    background: var(--ns-field-fill);
    background-clip: padding-box;
    box-shadow: var(--well);
    transition: box-shadow var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-field[data-invalid="true"] .ns-field__control {
    border-color: var(--ns-field-error);
  }

  .ns-field[data-disabled="true"] .ns-field__control {
    border-style: dashed;
  }

  .ns-field[data-readonly="true"]:not([data-disabled="true"]) .ns-field__control {
    border-style: dotted;
  }

  .ns-field[data-multiline="true"] .ns-field__control {
    height: auto;
  }

  .ns-field[data-label="placeholder"] .ns-field__input::placeholder {
    color: var(--ns-field-muted);
    opacity: 1;
  }

  .ns-field[data-kind="choice"] {
    padding-top: 0;
  }

  .ns-field[data-kind="choice"] .ns-field__control {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: var(--space-4, 0.49rem);
    height: auto;
    border: 0;
    background: none;
    box-shadow: none;
    border-radius: 0;
  }

  .ns-field[data-kind="choice"] .ns-field__label {
    position: static;
    transform: none;
    max-width: none;
    overflow: visible;
    text-overflow: unset;
    white-space: normal;
    color: var(--ns-field-fg);
    cursor: pointer;
    padding: 0;
    background: none;
  }

  .ns-field[data-kind="group"] {
    margin: 0;
    padding-top: 0;
    border: 0;
    min-width: 0;
  }

  .ns-field[data-disabled="true"][data-kind="choice"] .ns-field__label {
    color: var(--text-disabled, var(--ns-field-muted));
    cursor: not-allowed;
  }

  .ns-field__legend {
    padding: 0;
    color: var(--ns-field-fg);
    font: inherit;
    line-height: var(--leading, 1.5625);
  }

  .ns-field__options {
    display: flex;
    flex-direction: column;
    gap: var(--space-3, 0.39rem);
    min-width: 0;
  }

  .ns-field__sr {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .ns-field__input {
    appearance: none;
    display: block;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: var(--ns-field-inset-y) var(--ns-field-inset-x);
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: var(--ns-field-fg);
    font: inherit;
    line-height: inherit;
    letter-spacing: inherit;
  }

  .ns-field__input:disabled {
    color: var(--text-disabled, var(--ns-field-muted));
    cursor: not-allowed;
  }

  select.ns-field__input {
    appearance: auto;
    cursor: pointer;
    background-image: none;
  }

  @supports (appearance: base-select) {
    select.ns-field__input {
      appearance: base-select;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    select.ns-field__input::picker-icon {
      content: "";
      flex-shrink: 0;
      align-self: center;
      width: 0.36em;
      height: 0.36em;
      margin: 0;
      border: solid currentColor;
      border-width: 0 1.5px 1.5px 0;
      background: none;
      color: var(--ns-field-fg);
      transform: translateY(-0.12em) rotate(45deg);
    }

    select.ns-field__input::picker(select) {
      appearance: base-select;
      box-sizing: border-box;
      width: anchor-size(width);
      min-width: anchor-size(width);
      margin: 0;
      margin-block-start: var(--space-2, 0.31rem);
      padding: var(--inset-list, var(--space-2, 0.31rem));
      border: 1px solid
        var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
      border-radius: var(--radius-list, calc(var(--radius, 0.4rem) + var(--space-2, 0.31rem)));
      background: var(--bg, #fff);
      background-clip: padding-box;
      color: var(--text-sub, #767676);
      font: inherit;
      box-shadow: none;
    }

    select.ns-field__input:open::picker(select) {
      display: flex;
      flex-direction: column;
      align-items: stretch;
      gap: var(--space-1, 0.25rem);
    }

    select.ns-field__input option {
      display: flex;
      align-items: center;
      justify-content: flex-start;
      box-sizing: border-box;
      width: 100%;
      min-height: 0;
      margin: 0;
      padding: var(--space-1, 0.25rem) var(--space-3, 0.39rem);
      border: 1px solid transparent;
      border-radius: var(--radius, 0.4rem);
      background: none;
      background-clip: padding-box;
      font: inherit;
      line-height: inherit;
      color: var(--text-sub, #767676);
      box-shadow: var(--flat);
      gap: 0;
    }

    select.ns-field__input option:hover {
      color: var(--text-heading, #111);
      background: var(--bg-hover, #f3f2f1);
    }

    select.ns-field__input option:checked,
    select.ns-field__input option:focus {
      color: var(--text-heading, #111);
      border-color: var(--shade, oklch(0 0 0 / 28%));
      background: var(--bg-hover, #f3f2f1);
      box-shadow: var(--press);
    }

    select.ns-field__input option::checkmark {
      display: none;
      content: none;
    }
  }

  .ns-choice {
    appearance: none;
    display: inline-grid;
    place-content: center;
    box-sizing: border-box;
    flex-shrink: 0;
    width: 1.1em;
    height: 1.1em;
    margin: 0;
    padding: 0;
    border: 1px solid var(--ns-field-line);
    border-radius: calc(var(--ns-field-radius) * 0.7);
    background: var(--ns-field-fill);
    background-clip: padding-box;
    box-shadow: var(--well);
    color: var(--on-key, #111);
    cursor: pointer;
    transition:
      border-color var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      box-shadow var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      background var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-choice::after {
    content: "";
    width: 0.28em;
    height: 0.48em;
    border: solid currentColor;
    border-width: 0 0.12em 0.12em 0;
    transform: rotate(45deg) translate(-0.04em, -0.06em);
    opacity: 0;
  }

  .ns-choice[type="radio"] {
    border-radius: 999px;
  }

  .ns-choice[type="radio"]::after {
    width: 0.42em;
    height: 0.42em;
    border: 0;
    border-radius: 999px;
    background: currentColor;
    transform: none;
  }

  .ns-choice:checked {
    color: var(--on-key, #111);
    border-color: var(--key-line, #221898);
    background: var(--key-face);
    box-shadow: var(--press);
  }

  .ns-choice:checked::after {
    opacity: 1;
  }

  .ns-choice[data-kind="switch"] {
    width: 2em;
    height: 1.15em;
    border-radius: 999px;
  }

  .ns-choice[data-kind="switch"]::after {
    width: 0.72em;
    height: 0.72em;
    border: 0;
    border-radius: 999px;
    background: var(--face);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    transform: translateX(-0.36em);
    opacity: 1;
    transition: transform var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-choice[data-kind="switch"]:checked::after {
    background: var(--face);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    transform: translateX(0.36em);
  }

  .ns-choice:focus,
  .ns-choice:focus-visible {
    outline: none;
  }

  .ns-field[data-kind="choice"] .ns-field__control:focus-within {
    border-color: transparent;
    outline: none;
  }

  .ns-choice:focus-visible {
    outline: 5px auto Highlight;
    outline: 5px auto -webkit-focus-ring-color;
    outline-offset: 0;
  }

  .ns-field[data-invalid="true"] .ns-choice {
    border-color: var(--ns-field-error);
  }

  .ns-choice:disabled {
    color: var(--text-disabled, var(--ns-field-muted));
    cursor: not-allowed;
  }

  .ns-field__input::placeholder {
    color: transparent;
    opacity: 0;
  }

  textarea.ns-field__input {
    height: auto;
    resize: vertical;
    min-height: calc(
      var(--type-md, 1rem) * var(--leading, 1.5625) * 4 + var(--ns-field-inset-y) *
        2
    );
    line-height: var(--leading, 1.5625);
  }

  .ns-field__input::-webkit-search-decoration,
  .ns-field__input::-webkit-search-cancel-button {
    appearance: none;
  }

  .ns-field__input:-webkit-autofill,
  .ns-field__input:-webkit-autofill:hover,
  .ns-field__input:-webkit-autofill:focus {
    -webkit-text-fill-color: var(--ns-field-fg);
    caret-color: var(--ns-field-fg);
    box-shadow: 0 0 0 1000px var(--ns-field-fill) inset;
    transition: background-color 9999s ease-in-out 0s;
  }

  .ns-field__label {
    color: var(--ns-field-fg);
    cursor: default;
  }

  .ns-field[data-label="stack"] .ns-field__label,
  .ns-field[data-label="float"] .ns-field__label {
    position: static;
    max-width: none;
  }

  .ns-field__optional,
  .ns-field__required {
    color: var(--ns-field-muted);
  }

  .ns-field__meta {
    line-height: var(--leading, 1.5625);
  }

  .ns-field__description,
  .ns-field__error {
    overflow-wrap: anywhere;
  }

  .ns-field__description {
    color: var(--ns-field-muted);
  }

  .ns-field__error {
    color: var(--ns-field-error);
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-field__control,
    .ns-field__label,
    .ns-choice[data-kind="switch"]::after {
      transition: none;
    }
  }

  [dir="rtl"] .ns-choice[data-kind="switch"]::after {
    transform: translateX(0.36em);
  }

  [dir="rtl"] .ns-choice[data-kind="switch"]:checked::after {
    transform: translateX(-0.36em);
  }
}

.ns-field__input:focus,
.ns-field__input:focus-visible {
  outline: 5px auto Highlight;
  outline: 5px auto -webkit-focus-ring-color;
  outline-offset: 0;
}
